"use client"

import { Button, LinkButton } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { SemanticContent } from "@/components/ui/semantic-content"

/** Consent band: title, body, up to two actions and one policy link. */
export default function Consent({
  title = "Cookies on this site",
  body = "We use essential cookies to run the site. With your permission we also use analytics cookies to improve it.",
  actions = [
    { id: "decline", label: "Essential only" },
    { id: "accept", label: "Accept all" },
  ],
  policy = { label: "Cookie policy", href: "#" },
  onAction,
}: {
  title?: string
  body?: string
  actions?: { id: string; label: string }[]
  policy?: { label: string; href: string }
  onAction?: (id: string) => void
}) {
  return (
    <section data-slot="consent" role="region" aria-label={title} className="border-t border-border bg-background">
      <div className="mx-auto flex max-w-5xl flex-col gap-4 px-6 py-6 md:flex-row md:items-center">
        <Icon name="security" size="lg" className="hidden text-muted-foreground md:block" />
        <div className="flex-1 space-y-1">
          <SemanticContent as="h2" className="text-base">{title}</SemanticContent>
          <SemanticContent as="p" className="text-sm leading-6 text-muted-foreground">
            {body}{" "}
            <LinkButton href={policy.href} variant="link" className="h-auto p-0 align-baseline">
              {policy.label}
            </LinkButton>
          </SemanticContent>
        </div>
        <div className="flex gap-2">
          {actions.slice(0, 2).map((a, i) => (
            <Button key={a.id} variant={i === actions.length - 1 ? "default" : "outline"} onPress={() => onAction?.(a.id)}>
              {a.label}
            </Button>
          ))}
        </div>
      </div>
    </section>
  )
}
